package io.mavsdk.kotlin.plugins.failure

/** Inject failures into system to test failsafes. */
class Failure internal constructor(private val native: FailureNative) {
    private var closed = false

    /** Possible results returned for failure requests. */
    enum class Result(val value: Int) {
        /** Unknown result */
        UNKNOWN(0),
        /** Request succeeded */
        SUCCESS(1),
        /** No system is connected */
        NO_SYSTEM(2),
        /** Connection error */
        CONNECTION_ERROR(3),
        /** Failure not supported */
        UNSUPPORTED(4),
        /** Failure injection denied */
        DENIED(5),
        /** Failure injection is disabled */
        DISABLED(6),
        /** Request timed out */
        TIMEOUT(7);

        companion object {
            fun fromValue(value: Int): Result = entries.find { it.value == value } ?: UNKNOWN
        }
    }

    /** A failure unit. */
    enum class FailureUnit(val value: Int) {
        /** Gyro */
        SENSOR_GYRO(0),
        /** Accelerometer */
        SENSOR_ACCEL(1),
        /** Magnetometer */
        SENSOR_MAG(2),
        /** Barometer */
        SENSOR_BARO(3),
        /** GPS */
        SENSOR_GPS(4),
        /** Optical flow */
        SENSOR_OPTICAL_FLOW(5),
        /** Visual inertial odometry */
        SENSOR_VIO(6),
        /** Distance sensor */
        SENSOR_DISTANCE_SENSOR(7),
        /** Airspeed */
        SENSOR_AIRSPEED(8),
        /** Battery */
        SYSTEM_BATTERY(100),
        /** Motor */
        SYSTEM_MOTOR(101),
        /** Servo */
        SYSTEM_SERVO(102),
        /** Avoidance */
        SYSTEM_AVOIDANCE(103),
        /** RC signal */
        SYSTEM_RC_SIGNAL(104),
        /** MAVLink signal */
        SYSTEM_MAVLINK_SIGNAL(105),
        /** ESC telemetry */
        SYSTEM_ESC(106),
        /** Traffic avoidance system like ADS-B or FLARM */
        SYSTEM_TRAFFIC_AVOIDANCE(107),
        /** Data link over a cellular (LTE) connection */
        DATALINK_LTE(150),
        /** Data link over a Wi-Fi connection */
        DATALINK_WIFI(151),
        /** Data link over a telemetry radio, e.g. a SiK radio */
        DATALINK_TELEM_RADIO(152),
        /** CAN bus, instance is the bus number, e.g. 1 for CAN1 */
        BUS_CAN(200),
        /** I2C bus, instance is the bus number, e.g. 1 for I2C1 */
        BUS_I2C(201);

        companion object {
            fun fromValue(value: Int): FailureUnit =
                entries.find { it.value == value } ?: entries.first()
        }
    }

    /** A failure type */
    enum class FailureType(val value: Int) {
        /** No failure injected, used to reset a previous failure */
        OK(0),
        /** Sets unit off, so completely non-responsive */
        OFF(1),
        /** Unit is stuck e.g. keeps reporting the same value */
        STUCK(2),
        /** Unit is reporting complete garbage */
        GARBAGE(3),
        /** Unit is consistently wrong */
        WRONG(4),
        /** Unit is slow, so e.g. reporting at slower than expected rate */
        SLOW(5),
        /** Data of unit is delayed in time */
        DELAYED(6),
        /** Unit is sometimes working, sometimes not */
        INTERMITTENT(7),
        /** Unit is publishing plausible values but drifting away from true values */
        DRIFT(8);

        companion object {
            fun fromValue(value: Int): FailureType =
                entries.find { it.value == value } ?: entries.first()
        }
    }

    /**
     * Injects a failure.
     *
     * @param failureUnit The failure unit to send
     * @param failureType The failure type to send
     * @param instance Instance to affect (0 for all)
     * @return The result of the request.
     */
    fun inject(failureUnit: FailureUnit, failureType: FailureType, instance: Int): Result =
        Result.fromValue(native.inject(failureUnit, failureType, instance))

    internal fun destroy() {
        if (closed) return
        closed = true
        native.destroy()
    }

    class FailureException(val result: Result, message: String) : Exception(message)
}

internal interface FailureNative {
    fun inject(
        failureUnit: Failure.FailureUnit,
        failureType: Failure.FailureType,
        instance: Int,
    ): Int

    fun destroy()
}

internal expect fun createFailureNative(systemHandle: Long): FailureNative
